from pathlib import Path
import base64,gzip
root=Path(__file__).resolve().parents[1]
payloads={"1401":"","1402":"","1403":"","1404":"","summary":"","report":""}
targets={
"1401":"data/capacity/normalized/1401/capacities-radiotherapy-dental-prosthesis.csv",
"1402":"data/capacity/normalized/1402/capacities-radiotherapy-dental-prosthesis.csv",
"1403":"data/capacity/normalized/1403/capacities-radiotherapy-dental-prosthesis.csv",
"1404":"data/capacity/normalized/1404/capacities-radiotherapy-dental-prosthesis.csv",
"summary":"data/capacity/RADIOTHERAPY_DENTAL_PROSTHESIS_SUMMARY.json",
"report":"data/capacity/RADIOTHERAPY_DENTAL_PROSTHESIS_REPORT.md",
}
for k,rel in targets.items():
    out=root/rel
    out.parent.mkdir(parents=True,exist_ok=True)
    out.write_bytes(gzip.decompress(base64.b64decode(payloads[k])))
    print("wrote",rel)
